// One inbound message can carry text OR a voice note. Normalize both into
// a single `question` field so the agent below never has to care which.
//
// When the buffer grouped several messages, body.text.message already arrives
// joined and body.buffered is present — nothing extra to handle here, which is
// the point of concat mode.
const b = $input.first().json.body || {};

const spoken = b.transcription?.status === 'ok' ? (b.transcription.text || '') : '';
const typed = b.text?.message || '';
const question = (spoken || typed).trim();

return [{
  json: {
    phone: b.phone || '',
    question,
    isVoice: Boolean(spoken),
    grouped: Boolean(b.buffered),
    fromMe: Boolean(b.fromMe),
    isGroup: Boolean(b.isGroup),
    type: b.type || '',
  },
}];
